 <template #footer><el-button :disabled="operation.busy.value||!!operation.pending.value" @click="close()">关闭</el-button></template>
 <el-dialog v-model="batchOpen" title="创建加工批次" width="650px" class="storage-dialog" append-to-body :close-on-click-modal="false"><OperationStatus :operation="operation"/><div v-if="batchError" class="batch-refresh-error"><el-alert :title="batchError" type="error" :closable="false"/><el-button :loading="batchLoading" @click="refreshBatchSteps">重试</el-button></div><el-alert v-if="batchNotice" :title="batchNotice" type="warning" :closable="false"/><el-form label-position="top" :disabled="operation.busy.value||!!operation.pending.value"><el-form-item label="工单产品组" required><el-select v-model="batch.orderItemId" @change="batch.orderStepId='';batch.inheritedStockIds=[]"><el-option v-for="item in batchItems" :key="item.id" :label="`${item.product?.name||item.productName} / ${item.id}`" :value="String(item.id)"/></el-select></el-form-item><el-form-item label="目标工序" required><el-select v-model="batch.orderStepId" :loading="batchLoading" :disabled="!batch.orderItemId" :no-data-text="batchError?'工序加载失败，请重试':'暂无可创建批次的工序'" @visible-change="opened=>opened&&refreshBatchSteps()"><el-option v-for="s in batchSteps" :key="s.id" :label="`${s.sequenceNo} ${s.processName}`" :value="String(s.id||s.orderStepId)"/></el-select></el-form-item><el-form-item label="加工人员" required><el-select v-model="batch.processorId"><el-option v-for="p in createProcessors" :key="p.id" :label="p.name||p.nickName" :value="p.id"/></el-select></el-form-item><el-form-item label="本批计划件数"><el-input-number v-model="batch.plannedQuantity" :min="1" :precision="0"/></el-form-item><el-form-item label="承接已确认来源批次"><el-select v-model="batch.inheritedStockIds" multiple><el-option v-for="e in inheritedStocks" :key="e.id" :label="`${e.batchNo||e.id} / ${e.identity?.name||''} / ${e.netWeight}g`" :value="String(e.id)"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="batch.reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="batchOpen=false">取消</el-button><el-button type="primary" :disabled="operation.busy.value||!!operation.pending.value||batchLoading||!!batchError||!batchSteps.length||!batch.orderStepId" @click="saveBatch">创建</el-button></template></el-dialog>
 <el-dialog v-model="editOpen" title="编辑加工批次" width="650px" class="storage-dialog" append-to-body :close-on-click-modal="false" :before-close="closeEdit"><OperationStatus :operation="operation"/><el-alert v-if="editError" :title="editError" type="error" :closable="false"/><el-form v-if="!editLoading" label-position="top" :disabled="operation.busy.value||!!operation.pending.value">
 <el-form-item label="加工批次"><el-input :model-value="String(editForm.id||'')" readonly/></el-form-item><el-form-item label="目标工序"><el-input :model-value="editForm.processName" readonly/></el-form-item>
 <el-form-item label="加工人员" required><el-select v-model="editForm.processorId" aria-label="加工人员"><el-option v-if="editForm.processorId&&!processors.some(p=>String(p.id)===String(editForm.processorId))" :value="String(editForm.processorId)" :label="editForm.processorName||'原加工人员不可用'" disabled/><el-option v-for="p in processors" :key="p.id" :value="String(p.id)" :label="p.name||p.nickName"/></el-select></el-form-item>
 <el-form-item label="本批计划件数" :required="editForm.measurementMode==='PIECE'"><el-input-number v-model="editForm.plannedQuantity" :min="1" :max="2147483647" :precision="0"/></el-form-item><el-form-item label="修改原因" required><el-input v-model="editForm.reason" type="textarea" maxlength="500"/></el-form-item></el-form>
 <template #footer><el-button :disabled="operation.busy.value||!!operation.pending.value" @click="closeEdit()">取消</el-button><el-button type="primary" :loading="editLoading||operation.busy.value" :disabled="!!operation.pending.value||!!editError" @click="saveEdit">保存</el-button></template></el-dialog>
 <el-dialog v-model="exceptionOpen" title="申请异常完工" width="600px" append-to-body :close-on-click-modal="false"><OperationStatus :operation="operation"/><p>不足数量和当前物料余额仍保留，异常完工不会自动填平库存或欠料。</p><el-form label-position="top"><el-form-item label="指定审批人员" required><el-select v-model="exception.reviewerId"><el-option v-for="p in state.people.filter(p=>String(p.id)!==String(user.id))" :key="p.id" :label="p.name||p.nickName" :value="p.id"/></el-select></el-form-item><el-form-item label="异常原因" required><el-input v-model="exception.reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="exceptionOpen=false">取消</el-button><el-button :loading="operation.busy.value" :disabled="!!operation.pending.value||!exception.reviewerId||!exception.reason.trim()" @click="applyException">提交审批</el-button></template></el-dialog>
<BatchCloseDialog ref="closeDialog" :factory-id="props.factoryId" :order-id="id" :refresh="refreshAfterClose" @documents="tab='documents'"/>
 <OrderEditor ref="editor" @saved="load"/><DebtPanel v-model="debtsOpen" :order-id="id" @repay="row=>{debtsOpen=false;editor?.open('RETURN_RIGHTS',undefined,{debt:row})}"/>
</el-dialog></template>
<script setup lang="ts">
import DebtPanel from '../storage-live/DebtPanel.vue';import BatchCloseDialog from './BatchCloseDialog.vue';import {computed,ref,watch,onBeforeUnmount} from 'vue';import {ElMessageBox} from 'element-plus';import {useRouter} from 'vue-router';import request from '@/utils/request';import {useStorage,useOperation,message,type Row} from '../storage-live/client';import OperationStatus from '../storage-live/OperationStatus.vue';import OrderEditor from '../storage-orders/OrderEditor.vue';import {typeNames,statusNames} from '../storage-orders/model'
const props=defineProps<{factoryId:string}>(),emit=defineEmits<{changed:[]}>(),{state,user,can,context,loadOptions}=useStorage(),router=useRouter(),visible=ref(false),id=ref(''),data=ref<any>(),report=ref<any>(),error=ref(''),loading=ref(false),tab=ref('flow'),batchOpen=ref(false),exceptionOpen=ref(false),editor=ref<InstanceType<typeof OrderEditor>>()
const debtsOpen=ref(false)
const processingTypes:Record<string,string>={MATERIAL_CUSTOM:'来料定制',DIRECT_CUSTOM:'直接定制',SHORTAGE_CUSTOM:'欠料定制'}
const closeDialog=ref<InstanceType<typeof BatchCloseDialog>>()
async function refreshAfterClose(){await load();emit('changed');return !error.value}
const balanceColumns=[{key:'inputWeight',label:'投入（g）'},{key:'outputWeight',label:'产出（g）'},{key:'returnedWeight',label:'原样退回（g）'},{key:'recoveredWeight',label:'回收料（g）'},{key:'lossWeight',label:'损耗（g）'}]
const labels:Record<string,string>={INPUT:'领料投入',OUTPUT:'产出入库',RETURN:'原料还库',RECOVERY:'回收料入库',NORMAL:'普通工艺',ACID_WASH:'酸洗',SMELTING:'融定',RAW:'原材料',SEMI:'半成品',PRODUCT:'成品',WEIGHT:'计重',PIECE:'计件',OPEN:'加工中',CLOSED:'已结清',CANCELLED:'已取消'}
const totalColumns=[{key:'externalInputWeight',label:'整单外部净投入（g）'},{key:'finalOutputWeight',label:'成品产出（g）'},{key:'originalReturnWeight',label:'原料归还（g）'},{key:'recoveredWeight',label:'回收料（g）'},{key:'lossWeight',label:'加工损耗（g）'},{key:'inProcessWeight',label:'在制余额（g）'},{key:'intermediateStockWeight',label:'中间库存（g）'},{key:'handoverLossWeight',label:'交接损失（g）'},{key:'transferredToOtherOrdersWeight',label:'转出其他工单净重（g）'},{key:'intermediateDispatchWeight',label:'中间料出厂实收（g）'},{key:'balanceDifferenceWeight',label:'整单平衡差（g）'}]
const orderStates:Record<string,string>={CREATED:'已创建',IN_PROGRESS:'加工中',COMPLETED:'已完工',EXCEPTION_COMPLETED:'异常完工'}
const finished=computed(()=>['COMPLETED','EXCEPTION_COMPLETED'].includes(data.value?.order?.status)),customerSnapshot=computed(()=>{try{return JSON.parse(data.value?.order?.customerSnapshot||'{}')}catch{return {}}}),executionRows=computed(()=>(data.value?.executions||[]).map((e:any)=>({...e,number:e.number||String(e.id),processName:e.processName||data.value?.items?.flatMap((i:any)=>i.steps||[]).find((s:any)=>String(s.id||s.orderStepId)===String(e.orderStepId))?.processName||String(e.orderStepId),processorName:e.processorName||state.people.find(p=>p.id===String(e.processorId))?.name||String(e.processorId)})))
const batch=ref({orderItemId:'',orderStepId:'',processorId:'',plannedQuantity:1,inheritedStockIds:[] as string[],reason:''}),exception=ref({reviewerId:'',reason:''});let epoch=0
const inheritedStocks=ref<any[]>([])
const processors=computed(()=>state.people.filter(p=>p.canReceive===true)),createProcessors=computed(()=>processors.value)
const editOpen=ref(false),editLoading=ref(false),editError=ref(''),editForm=ref<any>({});let editEpoch=0,editInitial=''
async function openEdit(row:Row){
 if(operation.busy.value||operation.pending.value)return
 const req=++editEpoch,current=context(),order=id.value;editForm.value={...row,processorId:String(row.processorId),reason:''};editInitial=JSON.stringify(editForm.value);editError.value='';editOpen.value=true;editLoading.value=true
 const active=()=>req===editEpoch&&editOpen.value&&current===context()&&order===id.value
 try{const r:any=await request({url:`/metal/production-order/${order}/flow`,params:{factoryId:props.factoryId},quiet:true});if(!active())return;const latest=r.data.executions.find((e:any)=>String(e.id)===String(row.id));if(!latest||!latest.canEdit)throw Error(latest?.editDisabledReason||'批次已不可编辑，请刷新流程');editForm.value={...latest,processorId:String(latest.processorId),plannedQuantity:latest.plannedQuantity==null?undefined:Number(latest.plannedQuantity),reason:''};editInitial=JSON.stringify(editForm.value);await loadOptions()}
 catch(e){if(active())editError.value=message(e)}finally{if(active())editLoading.value=false}
}
async function saveEdit(){
 if(editLoading.value||editError.value||operation.busy.value||operation.pending.value)return
 if(!editForm.value.processorId){operation.error.value='请选择加工人员';return}
 if(!processors.value.some(p=>String(p.id)===String(editForm.value.processorId))){operation.error.value='所选加工人员不可用或没有领料复验权限，请重新选择';return}
 if(!editForm.value.reason?.trim()){operation.error.value='请填写修改原因';return}
 if(editForm.value.measurementMode==='PIECE'&&(!Number.isInteger(editForm.value.plannedQuantity)||editForm.value.plannedQuantity<1)){operation.error.value='请填写正整数计划件数';return}
 await operation.send(`/metal/production-order/executions/${editForm.value.id}`,{factoryId:props.factoryId,version:editForm.value.version,processorId:editForm.value.processorId,plannedQuantity:editForm.value.plannedQuantity??null,reason:editForm.value.reason},'put')
}
async function closeEdit(done?:()=>void){if(operation.busy.value||operation.pending.value)return;if(JSON.stringify(editForm.value)!==editInitial){try{await ElMessageBox.confirm('放弃未保存的批次修改？','确认关闭')}catch{return}}editEpoch++;editOpen.value=false;done?.()}
const batchItems=ref<any[]>([]),batchLoading=ref(false),batchError=ref(''),batchNotice=ref('');let batchEpoch=0,batchSession=0
const batchSteps=computed(()=>(batchItems.value.find(i=>String(i.id)===batch.value.orderItemId)?.steps||[]).filter((s:any)=>s.executionClosed!==true&&s.executionClosed!==1&&s.executionClosed!=='1'))
async function refreshBatchSteps(){
 if(!batchOpen.value||batchLoading.value||operation.busy.value||operation.pending.value)return false
 const req=++batchEpoch,current=context(),order=id.value,factory=props.factoryId
 const active=()=>req===batchEpoch&&batchOpen.value&&visible.value&&current===context()&&order===id.value&&factory===props.factoryId
 batchLoading.value=true;batchError.value=''
 try{
  const r:any=await request({url:`/metal/production-order/${order}/flow`,params:{factoryId:factory},quiet:true})
  if(!active())return false
  batchItems.value=['COMPLETED','EXCEPTION_COMPLETED'].includes(r.data.order?.status)?[]:r.data.items||[]
  if(batch.value.orderStepId&&!batchSteps.value.some((s:any)=>String(s.id||s.orderStepId)===batch.value.orderStepId)){
   batch.value.orderStepId='';batch.value.inheritedStockIds=[];batchNotice.value='所选工序已完成或不可用，请重新选择目标工序';return false
  }
  return true
 }catch(e){if(active())batchError.value='工序状态加载失败：'+message(e);return false}
 finally{if(active())batchLoading.value=false}
}
watch(batchOpen,()=>{batchEpoch++;batchSession++;batchLoading.value=false},{flush:'sync'})
watch(context,()=>{batchOpen.value=false;editOpen.value=false;editEpoch++})
onBeforeUnmount(()=>{batchEpoch++;batchSession++;editEpoch++})
const operation=useOperation('/metal/production-order/executions',context,async()=>{batchOpen.value=false;editOpen.value=false;exceptionOpen.value=false;emit('changed');await load()})
async function open(orderId:string){debtsOpen.value=false;id.value=orderId;state.factoryId=props.factoryId;visible.value=true;tab.value='flow';await load();if(can('metal:work-order:execute')||can('metal:warehouse-order:add')||can('metal:work-order:exception-close'))await loadOptions()}
async function load(){const current=context(),order=id.value,req=++epoch;loading.value=true;error.value='';try{const [f,r]:any[]=await Promise.all([request({url:`/metal/production-order/${order}/flow`,params:{factoryId:props.factoryId},quiet:true}),request({url:`/metal/production-order/${order}/report`,params:{factoryId:props.factoryId},quiet:true})]);if(current===context()&&req===epoch){data.value=f.data;report.value=r.data}}catch(e){if(req===epoch)error.value=message(e)}finally{if(req===epoch)loading.value=false}}
async function openBatch(){batch.value={orderItemId:'',orderStepId:'',processorId:'',plannedQuantity:1,inheritedStockIds:[],reason:''};batchItems.value=[];batchError.value='';batchNotice.value='';batchOpen.value=true;await refreshBatchSteps()}
watch(()=>batch.value.orderStepId,async step=>{inheritedStocks.value=[];batch.value.inheritedStockIds=[];if(!step||!batchOpen.value)return;batchNotice.value='';const current=context(),order=id.value,session=batchSession;try{const r:any=await request({url:`/metal/production-order/${order}/inheritance-options`,params:{factoryId:props.factoryId,orderStepId:step},quiet:true});if(current===context()&&order===id.value&&batchOpen.value&&session===batchSession&&step===batch.value.orderStepId)inheritedStocks.value=r.data||[]}catch(e){if(current===context()&&order===id.value&&batchOpen.value&&session===batchSession&&step===batch.value.orderStepId)operation.error.value=message(e)}})
async function saveBatch(){if(batchLoading.value||batchError.value||operation.busy.value||operation.pending.value)return;if(!await refreshBatchSteps())return;if(!batch.value.orderItemId||!batchSteps.value.some((s:any)=>String(s.id||s.orderStepId)===batch.value.orderStepId)||!batch.value.processorId){operation.error.value='请选择产品组、未完成工序和加工人员';return}await operation.send(`/metal/production-order/${id.value}/executions`,{factoryId:props.factoryId,...batch.value});if(batchOpen.value&&!operation.pending.value&&operation.error.value)await refreshBatchSteps()}
async function cancelBatch(row:Row){const current=context(),order=id.value;try{const answer=await ElMessageBox.prompt('请输入取消原因；只有没有实际流转、关联草稿已撤销的空批次可以取消。','取消空批次',{inputValidator:v=>!!v?.trim()||'请填写原因'});if(current===context()&&order===id.value){await operation.send(`/metal/production-order/executions/${row.id}/cancel`,{factoryId:props.factoryId,version:row.version,reason:answer.value});if(!operation.pending.value)await load()}}catch{}}
function closeBatch(row:Row){if(operation.busy.value||operation.pending.value)return;closeDialog.value?.open(row)}
async function completeStep(step:Row){const current=context(),order=id.value,version=data.value.order.version;try{await ElMessageBox.confirm('确认完成本工序？完成后不能再新建该工序加工批次，服务端将核对产出与未结事项。','完成工序')}catch{return}if(current===context()&&order===id.value)void operation.send(`/metal/production-order/${order}/steps/${step.id}/complete`,{factoryId:props.factoryId,version})}
async function complete(){try{await ElMessageBox.confirm('确认按计划数量完成本工单？所有加工批次及单据必须已结清。','正常完工')}catch{return}void operation.send(`/metal/production-order/${id.value}/complete`,{factoryId:props.factoryId,version:data.value.order.version})}
function applyException(){void operation.send(`/metal/production-order/${id.value}/exception-close`,{factoryId:props.factoryId,version:data.value.order.version,...exception.value})}
async function reviewException(row:Row,approve:boolean){try{const r=await ElMessageBox.prompt('请输入审批说明','异常完工审批',{inputValidator:v=>!!v?.trim()||'请输入说明'});void operation.send(`/metal/production-order/${id.value}/exception-close/${row.id}/review`,{factoryId:props.factoryId,version:row.version,approve,reason:r.value})}catch{}}
function document(row:Row,kind:'OUT'|'IN'|'RET'){const type=kind==='OUT'?'PRODUCTION_OUT':kind==='RET'?'RAW_RETURN':row.outputCategory==='RAW'?'PROCESS_RAW_IN':row.outputCategory==='PRODUCT'?'PRODUCT_IN':'SEMI_IN';editor.value?.open(kind,undefined,{orderId:id.value,executionId:row.id,type})}
function showStorage(row:Row){visible.value=false;void router.push({path:'/metal/storage-orders',query:{factoryId:props.factoryId,detail:row.id}})}
async function close(done?:()=>void){if(operation.busy.value||operation.pending.value)return;if(closeDialog.value&&!closeDialog.value.requestClose())return;if(editor.value&&!await editor.value.requestClose())return;visible.value=false;done?.()}
watch(()=>props.factoryId,()=>{epoch++;debtsOpen.value=false;batchOpen.value=false;visible.value=false});defineExpose({open})
</script><style scoped>.batch-refresh-error{display:flex;gap:12px;align-items:center;margin-bottom:12px}.batch-refresh-error .el-alert{flex:1}.actions{display:flex;gap:10px;margin:16px 0;flex-wrap:wrap}h3{font-size:15px;margin:20px 0 12px}.el-select{width:100%}.batch-actions{display:grid;grid-template-columns:repeat(3,max-content);gap:8px;padding:4px 0}.batch-actions .el-button{margin:0}.batch-actions .el-button:last-child:nth-child(6){grid-column:auto}.execution-table :deep(.cell){word-break:normal;overflow-wrap:anywhere}.execution-table :deep(.el-table__cell){padding:10px 0}</style>
